create table xxventuri.eba_sales_salesreps (
    id                     number,
    row_version_number     number,
    row_key                varchar2(255 byte),
    rep_last_name          varchar2(100 byte) not null disable,
    rep_first_name         varchar2(100 byte) not null enable,
    rep_email              varchar2(100 byte) not null enable,
    rep_manager_id         number,
    rep_eba_sales_username varchar2(255 byte),
    rep_role               number,
    rep_office             varchar2(255 byte),
    rep_office_phone       varchar2(100 byte),
    rep_cell_phone         varchar2(100 byte),
    rep_pager              varchar2(100 byte),
    svp_id                 number,
    created_by             varchar2(255 byte),
    created                timestamp(6) with local time zone,
    updated_by             varchar2(255 byte),
    updated                timestamp(6) with local time zone,
    internal_flex_flag_01  varchar2(30 byte),
    internal_flex_flag_02  varchar2(30 byte),
    internal_flex_flag_03  varchar2(30 byte),
    internal_flex_flag_04  varchar2(30 byte),
    internal_flex_01       varchar2(4000 byte),
    internal_flex_02       varchar2(4000 byte),
    internal_flex_03       varchar2(4000 byte),
    internal_flex_04       varchar2(4000 byte),
    flex_flag_01           varchar2(30 byte),
    flex_flag_02           varchar2(30 byte),
    flex_flag_03           varchar2(30 byte),
    flex_flag_04           varchar2(30 byte),
    flex_flag_05           varchar2(30 byte),
    flex_flag_06           varchar2(30 byte),
    flex_flag_07           varchar2(30 byte),
    flex_flag_08           varchar2(30 byte),
    flex_01                varchar2(4000 byte),
    flex_02                varchar2(4000 byte),
    flex_03                varchar2(4000 byte),
    flex_04                varchar2(4000 byte),
    flex_05                varchar2(4000 byte),
    flex_06                varchar2(4000 byte),
    flex_07                varchar2(4000 byte),
    flex_08                varchar2(4000 byte),
    flex_d01               timestamp(6) with local time zone,
    flex_d02               timestamp(6) with local time zone,
    flex_d03               timestamp(6) with local time zone,
    flex_d04               timestamp(6) with local time zone,
    flex_n01               number,
    flex_n02               number,
    flex_n03               number,
    flex_n04               number,
    flex_n05               number,
    flex_n06               number,
    flex_n07               number,
    flex_n08               number,
    user_name              varchar2(100 byte),
    password               varchar2(50 byte),
    designation            varchar2(100 byte),
    date_of_joining        date,
    address                varchar2(1000 byte),
    emergency_contact      varchar2(1000 byte),
    department_id          varchar2(500 byte),
    status                 char(1 byte),
    meetings_per_day       number,
    working_days           varchar2(100 byte),
    file_blob              blob,
    attach_mimetype        varchar2(255 byte),
    attach_filename        varchar2(255 byte),
    attach_charset         varchar2(128 byte),
    attach_last_update     date,
    mpin                   nvarchar2(10)
);

alter table xxventuri.eba_sales_salesreps add primary key ( id )
    using index enable;


